import os
import socket
import select
import threading
import time
from robot.api import logger as r_logger
from ta_pcmd.logger_config import configure_logger
import psutil

IP = '10.0.1.1'
PORT = 49151
PACKET_SIZE = 2048
CONNECT_TIMEOUT = 60
READ_READY_TIMEOUT = 0.1


class PcmdServer(object):
    def __init__(self, ip=IP, port=PORT, clients=1):
        self.ip = ip
        self.port = port
        self.expected_num_of_client = int(clients)
        self.logger = configure_logger('ta_pcmd.server_{}_{}_{}'.format(self.ip, self.port, clients))
        self.server_address = (self.ip, int(self.port))
        self.connections = []
        self.client_addresses = []
        self.is_running = [threading.Event()] * self.expected_num_of_client
        self._started = [threading.Semaphore(0)] * self.expected_num_of_client
        self._stopped = [threading.Semaphore(0)] * self.expected_num_of_client
        self.pcmd_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        try:
            self._wait_for_enb_client_to_connect()
        except Exception as e:
            self.logger.debug('Received exception: {}\nGracefully shutting down all connections'.format(e))
            self.stop()
            raise e
        self._start_pcmd_server_thread()
        for client_started in self._started:
            client_started.acquire()

    def stop(self):
        ''' to be used only when all threads are succusfylly started '''
        for connection_index, connection in enumerate(self.connections):
            if self.is_running[connection_index].is_set():
                self.logger.debug('Threads are running in pcmd server, stopping them and then closing connection')
                self.is_running[connection_index].clear()
                self.logger.debug('Waiting till thread closes the connection')
                self._stopped[connection_index].acquire()
                self.logger.debug('Connection closed')
            else:
                self.logger.debug('Threads are not running in pcmd server, closing opened connection')
                self._close_connection(connection)

    def start(self, connection):
        ''' to be added '''
        connection_index = self.connections.index(connection)
        self.is_running[connection_index].set()
        self._started[connection_index].release()
        self.logger.debug("Entering receive loop for connection index: {}/{}"
                          .format(connection_index + 1, len(self.connections)))
        try:
            while self.is_running[connection_index].is_set():
                ready = select.select([self.pcmd_socket], [], [], READ_READY_TIMEOUT)
                if ready[0]:
                    self._receive_data(connection)
        finally:
            self.logger.debug('Connection: {}/{} to be terminated'.format(self.connections.index(connection) + 1,
                                                                          len(self.connections)))
            self._close_connection(connection)

    def _start_pcmd_server_thread(self):
        self.pcmd_server_threads = []
        for conn in self.connections:
            pcmd_server_thread = threading.Thread(target=self.start, args=(conn,))
            self.pcmd_server_threads.append(pcmd_server_thread)
            pcmd_server_thread.start()

    def _check_if_port_is_used(self, port):
        used_ports = [int(conn.laddr.port) for conn in psutil.net_connections()]
        return True if int(port) in used_ports else False

    def _actions_on_port_used(self):
        user_message = 'ta_pcmd: Port: {} is used by other tool. Library to work attempts to free the port.\n'\
                       'Consider NOT USING different tools (like DCAP) to collect pcmd/tracing\n' \
                       'while running ta_pcmd library as they are sharing the same port configuration!'\
                       .format(self.server_address[1])
        r_logger.warn(user_message)
        self.logger.debug(user_message)
        self._stop_dcap_docker()

    def _stop_dcap_docker(self):
        stop_ltetracer_docker_cmd = 'sudo docker stop ltetracer'
        try:
            # hardcoded version of docker name, could be searched dynamically in the future
            out = os.system(stop_ltetracer_docker_cmd)
            if out == 0:
                msg = 'Command: {} succeeded, docker is stopped'.format(stop_ltetracer_docker_cmd)
                print(msg)
                self.logger.debug(msg)
            else:
                msg = 'Command: {} failed, docker not found/not stopped'.format(stop_ltetracer_docker_cmd)
                print(msg)
                self.logger.debug(msg)
        except Exception as e:
            msg = 'Stopping dcap docker failed due to exception: {}'.format(e)
            print(msg)
            self.logger.debug(msg)

    def _wait_for_enb_client_to_connect(self):
        pcmd_port = self.server_address[1]
        port_used = False
        try:
            port_used = self._check_if_port_is_used(port=pcmd_port)
            self.logger.debug('Determined that port: {} is: {}'
                              .format(pcmd_port, 'used' if port_used is True else 'free'))
        except Exception as e:
            msg = 'Could not retrieve used ports due to exception: {}. Assuming port is free.'.format(e)
            self.logger.debug(msg)
            print(msg)
        if port_used:
            self._actions_on_port_used()
            time.sleep(2)
            recheck_port_used = self._check_if_port_is_used(port=pcmd_port)
            msg = 'Verified that after actions port: {} is: {}'\
                .format(pcmd_port, 'used' if recheck_port_used is True else 'free')
            print(msg)
            self.logger.debug(msg)
            if recheck_port_used is True:
                msg = 'Port is still used, skipping further actions and allowing to fail in socket connection attempt'
                print(msg)
                self.logger.debug(msg)
        self.pcmd_socket.settimeout(CONNECT_TIMEOUT)
        self.pcmd_socket.bind(self.server_address)
        self.pcmd_socket.listen(self.expected_num_of_client)
        self.logger.debug('Started waiting for: {} clients to connect'.format(self.expected_num_of_client))
        while len(self.connections) < self.expected_num_of_client:
            try:
                connection, client_address = self.pcmd_socket.accept()
                self.connections.append(connection)
                self.client_addresses.append(client_address)
            except socket.timeout:
                self.logger.error("BTS not connected within {} seconds".format(CONNECT_TIMEOUT))
                self.logger.error("Number of established PCMD connections: {}".format(len(self.connections)))
                if self.expected_num_of_client > 1:
                    exc_add_text = "\nNumber of successfull connections: {}/{}" \
                        .format(len(self.connections), self.expected_num_of_client)
                else:
                    exc_add_text = ""
                raise Exception("BTS not connected to PCMD server. Check if MTRACE object is configured.{}"
                                .format(exc_add_text))
            else:
                self.logger.debug("BTS connected with address: {}".format(client_address))

    def _receive_data(self, connection):
        data = connection.recv(PACKET_SIZE)
        self.logger.debug("Received from eNB: '{}'".format(repr(data)))
        return data

    def _shutdown_socket(self):
        self.pcmd_socket.shutdown(socket.SHUT_RDWR)
        self.pcmd_socket.close()

    def _close_connection(self, connection):
        connection_index = self.connections.index(connection)
        try:
            self._shutdown_socket()
            self.pcmd_socket.close()
            self.logger.debug('PCMD listening socket shut down completed')
        except Exception:
            self.logger.debug('Socket already closed by other connection, ignoring')
        try:
            connection.shutdown(socket.SHUT_RDWR)
            self.logger.debug('Connection socket closed')
        except OSError:
            self.logger.debug('Connection already closed probably during exception handling, ignoring')
        connection.close()
        self.logger.debug("Disconnected {}/{} connection from BTS."
                          .format(int(connection_index) + 1, len(self.connections)))
        self._stopped[connection_index].release()
